#[test]
#[cfg_attr(miri, ignore = "calls C")]
fn a_stream_not_open_for_writing_fails_alike() {
    let writes: [&[u8]; 3] = [b"text", b"", b"more"];
    compare(
        &Stream::fixed(16, c"r"),
        &Stream::fixed(16, c"r"),
        c_fwrite,
        &writes,
    );
    compare(
        &Stream::fixed(16, c"r"),
        &Stream::fixed(16, c"r"),
        c_fprintf,
        &[b"text", b"more"],
    );
