    // unread bytes, which a socket cannot, and fails with `ESPIPE`, setting no indicator. The
    // first line fails short; the second fits the buffer, and `fwrite` returns its full count.
    let writes: [&[u8]; 3] = [b"ab\n", b"cd\n", b"ef"];
    compare_flushing(
